import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"백오피스 기획은 개발자가 하나요?","description":"기획자도 운영팀도 없는 조직에서 개발자가 임시로 채운 백오피스가, 결국 누구도 책임지지 않는 화면이 되어버린 이야기입니다.","frontmatter":{"title":"백오피스 기획은 개발자가 하나요?","date":"2026-05-31T18:35+09:00","description":"기획자도 운영팀도 없는 조직에서 개발자가 임시로 채운 백오피스가, 결국 누구도 책임지지 않는 화면이 되어버린 이야기입니다.","tags":["backoffice","product-management","development"]},"headers":[],"relativePath":"posts/backoffice.md","filePath":"posts/backoffice.md","lastUpdated":1787309558000}`),a={name:`posts/backoffice.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="백오피스-기획은-개발자가-하나요" tabindex="-1">백오피스 기획은 개발자가 하나요? <a class="header-anchor" href="#백오피스-기획은-개발자가-하나요" aria-label="Permalink to “백오피스 기획은 개발자가 하나요?”">​</a></h1><blockquote><p>&quot;시스템 계정에 접속하면 나오는 수치가 맞지 않으니까 수정해주세요.&quot;</p></blockquote><p>임원의 한마디로 하루가 시작되는 날이 있어요. 머릿속에 가장 먼저 떠오르는 말은 <em>애초에 어떤 지표가 보여야 하는지 이야기 해본 적이 없는데</em> 였어요.</p><p>백오피스 기획(대시보드의 초기 요구사항)이 없는 상태에서 프론트엔드 개발자가 임의로 구성해서 남아있던 화면이었어요.</p><h2 id="백오피스의-가짜-데이터" tabindex="-1">백오피스의 가짜 데이터 <a class="header-anchor" href="#백오피스의-가짜-데이터" aria-label="Permalink to “백오피스의 가짜 데이터”">​</a></h2><p>임원들은 평소 시스템에 접속하지 않아요. 의사결정에 대시보드를 쓰는 일도 없고요. 그러다 어쩌다 마주친 숫자가 이상하다 싶으면, <em>수정해달라</em> 는 한마디가 뜬금없이 개발팀에 떨어집니다.</p><p>사실 그 지표는 어떤 데이터와도 연동되지 않은 숫자였어요. 디자인하면서 자리에 채워둔 가짜 데이터였고, 실제 값으로 갈아끼우는 단계는 끝내 오지 않았습니다.</p><p>실제 지표가 아니라, 임의로 넣었던 가짜 데이터였습니다.</p><h2 id="기획자가-없다면-결국-개발자가" tabindex="-1">기획자가 없다면 결국 개발자가 <a class="header-anchor" href="#기획자가-없다면-결국-개발자가" aria-label="Permalink to “기획자가 없다면 결국 개발자가”">​</a></h2><p>백오피스 기획에 대해 찾아보면, 개발자가 아니라 <em>서비스 운영 흐름을 아는 서비스 운영팀</em>이 주체가 되어야 한다고 말합니다. 하지만 지금 조직에는 서비스 기획자도 운영팀도 없어요.</p><p>결국 사용자는 개발자 뿐이므로 백오피스는 <em>본인 업무에 필요하다고 느낀 기능</em> 만을 만들고 대시보드는 임의로 채워둔 화면이 되어버렸어요. <strong>가짜 데이터로 남을거라면 처음부터 만들지 않는게 낫습니다.</strong> 아마도, 개발자가 대시보드를 정의했을때 <mark>검토를 요청해도 임원들은 리뷰하지 않았을</mark> 거에요. AI 시대에 <em>바이브 코딩</em>이 보편화되면서 리뷰의 중요성이 어느 때보다 강조되고 있는데도요. 결국 주요 원인은 개발팀이 아니라 <mark><em>조직의 업무 습관</em></mark> 입니다.</p><p>개발자가 알아서 만들어야 하는 상황은 언제나 생깁니다. 다만, 그게 <strong>조직의 기본값</strong> 이 되어서는 안되겠죠. 조직이 서비스 제품을 만들기로 했다면, 백오피스는 <em>나중에 할 일</em> 이 아니라 처음부터 함께 고려해야 합니다.</p>`,12)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};